void OptimizerManager::create_image_indices(
    std::vector<int>& img_indices, int start, int end) {
    if (start < end) {
        for (int i = start; i <= end; i++) {
            img_indices.push_back(i);
        }
    } else if (start > end) {
        for (int i = start; i >= end; i--) {
            img_indices.push_back(i);
        }
    } else if (start == end) {
        int i = start;
        img_indices.push_back(i);
    }
}

